mapper.select:
select atc.id as id, atc.name as name, count(distinct(aa.id)) as num from asset_asset aa left join asset_type_conf atc on aa.type_id = atc.id
left join monitor_endpoint me on aa.id = me.asset_id left join monitor_module mm on me.module_id = mm.id left join monitor_project mp on mm.project_id = mp.id
where 1=1
and aa.state_id = #{params.stateId}
and mp.id = #{params.projectId}
and aa.dc_id = #{params.dcId}
group by aa.type_id

select ascc.id as id,
ascc.name as name,
count(distinct(aa.id)) as num
from asset_asset aa left join asset_state_conf ascc on aa.state_id = ascc.id

	left join monitor_endpoint me on aa.id = me.asset_id
	left join monitor_module mm on me.module_id = mm.id
	left join monitor_project mp on mm.project_id = mp.id

where 1=1

	and aa.type_id = #{params.typeId}


	and aa.model_id = #{params.modelId}


	and mp.id = #{params.projectId}


	and mm.id = #{params.moduleId}


	and aa.dc_id = #{params.dcId}

group by aa.state_id

select am.id as id,
am.name as name,
count(distinct(aa.id)) as num
from asset_asset aa left join asset_model am on aa.model_id = am.id

	left join monitor_endpoint me on aa.id = me.asset_id
	left join monitor_module mm on me.module_id = mm.id
	left join monitor_project mp on mm.project_id = mp.id

where 1=1

	and aa.dc_id = #{params.dcId}


	and aa.type_id = #{params.typeId}


	and aa.state_id = #{params.stateId}


	and mp.id = #{params.projectId}


	and mm.id = #{params.moduleId}

group by aa.model_id;

select ap.status,
count(distinct(aa.id)) as num
from asset_asset aa left join asset_ping ap on aa.manage_ip = ap.host

	left join monitor_endpoint me on aa.id = me.asset_id
	left join monitor_module mm on me.module_id = mm.id
	left join monitor_project mp on mm.project_id = mp.id

where 1=1

	and aa.dc_id = #{params.dcId}


	and aa.type_id = #{params.typeId}


	and aa.state_id = #{params.stateId}


	and aa.model_id = #{params.modelId}


	and mp.id = #{params.projectId}


	and mm.id = #{params.moduleId}

group by ap.status

select afm.id as id,
afm.name as name,
afv.value as value,
count(*) as num
from asset_field_value afv left join asset_asset aa on afv.asset_id = aa.id
left join asset_field_meta afm on afv.meta_id = afm.id

	left join monitor_endpoint me on aa.id = me.asset_id
	left join monitor_module mm on me.module_id = mm.id
	left join monitor_project mp on mm.project_id = mp.id

where 1=1

	and aa.dc_id = #{params.dcId}


	and mp.id = #{params.projectId}


	and mm.id = #{params.moduleId}


	and aa.type_id = #{params.typeId}


	and aa.model_id = #{params.modelId}


	and aa.state_id = #{params.stateId}


	and afm.id = #{params.fieldId}

group by afm.id

select 	mm.type as name,
count(distinct (me.id))num
from monitor_endpoint me left join monitor_module mm on me.module_id = mm.id

	left join endpoint_state es on me.id = es.endpoint_id


	left join asset_asset aa on me.asset_id = aa.id 

where 1=1 

	and mm.project_id = #{params.projectId}


	and me.module_id = #{params.moduleId}


	and es.state = #{params.state}


	and me.asset_id = #{params.assetId}


	and aa.dc_id = #{params.dcId}

group by mm.type

select 	case when es.state =0 then 'down' when es.state=1 then 'up' else 'suspended' end as name,
count(distinct (me.id))num
from monitor_endpoint me left join endpoint_state es on me.id = es.endpoint_id

	left join monitor_module mm on me.module_id = mm.id	


	left join asset_asset aa on me.asset_id = aa.id 

where 1=1 

	and mm.project_id = #{params.projectId}


	and me.module_id = #{params.projectId}


	and mm.type = #{params.type}


	and me.asset_id = #{params.assetId}


	and aa.dc_id = #{params.dcId}

group by es.state

select am.state,
count(am.id) as num
from (select * from alert_message_active union all select * from alert_message_history union all select * from alert_message_silence) am
where 1=1 

	and am.project_id = #{params.projectId}


	and am.module_id = #{params.moduleId}


	and am.endpoint_id = #{params.endpointId}


	and am.dc_id = #{params.dcId}


	and am.asset_id = #{params.assetId}


	and am.rule_id = #{params.ruleId}

group by am.state

select ascc.name as name,
count(am.id) as num
from alert_message_active am left join alert_severity_conf ascc on am.severity_id = ascc.id
where 1=1 

	and project_id = #{params.projectId}


	and module_id = #{params.moduleId}


	and endpoint_id = #{params.endpointId}


	and dc_id = #{params.dcId}


	and asset_id = #{params.assetId}

group by ascc.id

select t.id as id, t.name as name, count(am.id) as num from alert_message_active am
right join monitor_project t on am.project_id = t.id
right join monitor_module t on am.module_id = t.id
right join monitor_endpoint t on am.endpoint_id = t.id
right join dc t on am.dc_id = t.id
right join asset_asset t on am.asset_id = t.id
right join alert_rule t on am.rule_id = t.id
where 1=1
and am.project_id = #{params.projectId}
and am.module_id = #{params.moduleId}
and am.dc_id = #{params.dcId}
group by t.id order by num desc limit 0,#{params.size}

select case when status =0 then 'down' when status=1 then 'up' end name, count(id) as num from prom_server where 1=1
and dc_id = #{params.dcId}
and type = #{params.type}
group by status

select case when type =1 then 'global' when type=2 then 'per_datacenter' end name, count(id) as num from prom_server where 1=1
and dc_id = #{params.dcId}
and state = #{params.state}
group by type

select count(*) as num
from asset_asset aa 

	left join monitor_endpoint me on aa.id = me.asset_id
	left join monitor_module mm on me.module_id = mm.id
	left join monitor_project mp on mm.project_id = mp.id

where 1=1 

	and aa.dc_id = #{params.dcId}


	and mp.id = #{params.projectId}


	and mm.id = #{params.moduleId}


	and aa.type_id = #{params.typeId}


	and aa.model_id = #{params.modelId}


	and aa.state_id = #{params.stateId}

select dc.id as id, dc.name as name, count(*) as num from asset_asset aa left join dc on aa.dc_id = dc.id where 1=1
and aa.type_id = #{params.typeId}
and aa.state_id = #{params.stateId}
group by aa.dc_id

select ascc.name as name, count(*) as num from alert_rule ar left join alert_severity_conf ascc on ar.severity_id = ascc.id where 1=1
and ar.severity_id = #{params.severityId}
group by ar.severity_id

select count(*) as num
from alert_message_active am
where 1=1 

	and am.project_id = #{params.projectId}


	and am.module_id = #{params.moduleId}


	and am.endpoint_id = #{params.endpointId}


	and am.dc_id = #{params.dcId}


	and am.asset_id = #{params.assetId}


	and am.rule_id = #{params.ruleId}


	and am.severity_id = #{params.severityId}

select count(*) as num
from prom_server ps 
where 1=1 

	and ps.type = #{params.type}


	and ps.dc_id = #{params.dcId}

select t.id as id, t.name as name, count(*) as num from asset_asset aa
left join asset_model t on aa.model_id = t.id
left join asset_type_conf t on aa.type_id = t.id
where 1=1
and aa.dc_id = #{params.dcId}
and aa.state_id = #{params.stateId}
group by aa.model_id
group by aa.type_id
order by num desc limit 0,#{params.size}

select mm.id as id, mm.name as name, count(DISTINCT me.id) as num from monitor_module mm left join monitor_endpoint me on mm.id = me.module_id where 1=1
and mm.project_id = #{params.project_id}
group by mm.id order by num desc limit 0,#{params.size}

select count(*) as num
from monitor_endpoint me 

	left join monitor_module mm on me.module_id = mm.id
	left join monitor_project mp on mm.project_id = mp.id


	left join asset_asset aa on me.asset_id = aa.id

where 1=1

	and me.asset_id = #{params.assetId}


	and mp.id = #{params.projectId}


	and me.module_id = #{params.moduleId}


	and aa.dc_id = #{params.dcId}


	and me.enabled = #{params.state}

select distinct me.id from monitor_module mm left join monitor_endpoint me on mm.id = me.module_id left join monitor_endpoint_state mes on me.id = mes.endpoint_id where me.id is not null and mes.state < 1
and mm.project_id = #{params.projectId}
and mm.id = #{params.moduleId}

select distinct me.id endpoint, ama.asset_id asset from monitor_module mm left join monitor_endpoint me on mm.id = me.module_id left join alert_message_active ama on me.id = ama.endpoint_id where me.id is not null and ama.state is not null
and mm.project_id = #{params.projectId}
and mm.id = #{params.moduleId}

select mm.id id, mm.name name, count(*) alert from monitor_module mm left join alert_message_active ama on mm.id = ama.module_id
ama.id is not null
and mm.project_id = #{params.projectId}
and mm.id = #{params.moduleId}
group by ama.module_id

select distinct mm.id id, aa.id asset from monitor_module mm left join monitor_endpoint me on mm.id = me.module_id left join asset_asset aa on me.asset_id = aa.id where aa.id is not null
and mm.project_id = #{params.projectId}
and mm.id = #{params.moduleId}

    	SELECT
			date_format(start_at, #{params.step}) AS time,
			COUNT(1) as num
		FROM
			alert_message_history  amh


				and start_at > #{params.stime}


				and start_at < #{params.etime}


				and amh.dc_id = #{params.dcId}


				and amh.project_id = #{params.projectId}


				and amh.module_id = #{params.moduleId}


				and amh.asset_id = #{params.assetId}


				and amh.endpoint_id = #{params.endpointId}


				and amh.rule_id = #{params.ruleId}


				and amh.severity_id = #{params.severityId}


		GROUP BY
			TIME 
		ORDER BY
			TIME
